    if (!ml.load(gguf)) { std::fprintf(stderr, "load failed\n"); return 1; }
    const auto& c = ml.config();
    bool ok = c.embed_dim == 768 && c.depth == 12 && c.num_heads == 12 &&
              c.head_dim == 64 && c.alt_start == 4 && c.rope_start == 4 &&
              c.qknorm_start == 4 && c.out_layers.size() == 4;
    ok = ok && ml.tensor("vit.patch_embed.weight") != nullptr;
    ok = ok && ml.tensor("vit.blk.0.attn_qkv.weight") != nullptr;
    ok = ok && ml.tensor("vit.blk.11.mlp_fc2.weight") != nullptr;
    std::fprintf(stderr, "embed=%u depth=%u heads=%u -> %s\n",
                 c.embed_dim, c.depth, c.num_heads, ok ? "OK" : "FAIL");
    return ok ? 0 : 1;
}

// Verifies the dense C-API: da_capi_depth_dense + da_capi_points for a DualDPT
// model (base f32) and, if available, a mono model (mono-large f32).
#include "da_capi.h"
#include <cstdlib>
#include <cstdio>
#include <cmath>

static bool finite_all(const float* p, int n){
    for (int i = 0; i < n; ++i) if (!std::isfinite(p[i])) return false;
    return true;
}

// DualDPT: depth+conf present, sky NULL, plausible pose; points return N>0.
static bool test_dualdpt(const char* gguf, const char* png){
    da_ctx* c = da_capi_load(gguf, 1);
    if (!c){ std::fprintf(stderr, "dualdpt: load failed\n"); return false; }
    int H=0, W=0, is_metric=-1; float *depth=nullptr, *conf=nullptr, *sky=nullptr;
    float ext[12], intr[9];
    int r = da_capi_depth_dense(c, png, &H, &W, &depth, &conf, &sky, ext, intr, &is_metric);
    bool ok = (r == 0) && H>0 && W>0 && depth && conf && !sky;
    if (ok) ok = finite_all(depth, H*W) && finite_all(conf, H*W);
    // Plausible pose: intrinsics fx,fy > 0; extrinsics finite.
    if (ok) ok = (intr[0] > 0.f) && (intr[4] > 0.f) && finite_all(ext, 12) && finite_all(intr, 9);
    if (ok) ok = (is_metric == 0); // base is a relative (non-metric) DualDPT
    std::fprintf(stderr, "dualdpt dense: r=%d %dx%d depth=%p conf=%p sky=%p fx=%.3f fy=%.3f is_metric=%d -> %s\n",
                 r, W, H, (void*)depth, (void*)conf, (void*)sky, intr[0], intr[4], is_metric, ok?"OK":"FAIL");
    da_capi_free_floats(depth); da_capi_free_floats(conf); da_capi_free_floats(sky);

    int N=0; float* xyz=nullptr; unsigned char* rgb=nullptr;
    int rp = da_capi_points(c, png, 0.0f, &N, &xyz, &rgb);
    bool okp = (rp == 0) && N > 0 && xyz && rgb && finite_all(xyz, 3*N);
    std::fprintf(stderr, "dualdpt points: r=%d N=%d xyz=%p rgb=%p -> %s\n",
                 rp, N, (void*)xyz, (void*)rgb, okp?"OK":"FAIL");
    da_capi_free_floats(xyz); da_capi_free_bytes(rgb);
    da_capi_free(c);
    return ok && okp;
}

// mono: depth+sky present, conf NULL; points return -1.
static bool test_mono(const char* gguf, const char* png){
    da_ctx* c = da_capi_load(gguf, 1);
    if (!c){ std::fprintf(stderr, "mono: load failed\n"); return false; }
    int H=0, W=0, is_metric=-1; float *depth=nullptr, *conf=nullptr, *sky=nullptr;
    float ext[12], intr[9];
    int r = da_capi_depth_dense(c, png, &H, &W, &depth, &conf, &sky, ext, intr, &is_metric);
    bool ok = (r == 0) && H>0 && W>0 && depth && sky && !conf;
    if (ok) ok = finite_all(depth, H*W) && finite_all(sky, H*W);
    if (ok) ok = (is_metric == 1); // DA3MONO is metric
    std::fprintf(stderr, "mono dense: r=%d %dx%d depth=%p conf=%p sky=%p is_metric=%d -> %s\n",
                 r, W, H, (void*)depth, (void*)conf, (void*)sky, is_metric, ok?"OK":"FAIL");
    da_capi_free_floats(depth); da_capi_free_floats(conf); da_capi_free_floats(sky);

    int N=0; float* xyz=nullptr; unsigned char* rgb=nullptr;
    int rp = da_capi_points(c, png, 0.0f, &N, &xyz, &rgb);
    bool okp = (rp == -1) && !xyz && !rgb; // mono has no pose
    std::fprintf(stderr, "mono points: r=%d (expect -1) err=\"%s\" -> %s\n",
                 rp, da_capi_last_error(c), okp?"OK":"FAIL");
    da_capi_free_floats(xyz); da_capi_free_bytes(rgb);
    da_capi_free(c);
    return ok && okp;
}

// nested: two-branch metric model via da_capi_load_nested. depth present, conf
// and sky NULL, is_metric==1, plausible pose.
static bool test_nested(const char* anyview, const char* metric, const char* png){
    da_ctx* c = da_capi_load_nested(anyview, metric, 1);
    if (!c){ std::fprintf(stderr, "nested: load failed\n"); return false; }
    int H=0, W=0, is_metric=-1; float *depth=nullptr, *conf=nullptr, *sky=nullptr;
    float ext[12], intr[9];
    int r = da_capi_depth_dense(c, png, &H, &W, &depth, &conf, &sky, ext, intr, &is_metric);
    bool ok = (r == 0) && H>0 && W>0 && depth && !conf && !sky;
    if (ok) ok = finite_all(depth, H*W);
    if (ok) ok = (intr[0] > 0.f) && (intr[4] > 0.f) && finite_all(ext, 12) && finite_all(intr, 9);
    if (ok) ok = (is_metric == 1);
    std::fprintf(stderr, "nested dense: r=%d %dx%d depth=%p conf=%p sky=%p fx=%.3f is_metric=%d -> %s\n",
                 r, W, H, (void*)depth, (void*)conf, (void*)sky, intr[0], is_metric, ok?"OK":"FAIL");
    da_capi_free_floats(depth); da_capi_free_floats(conf); da_capi_free_floats(sky);
    da_capi_free(c);
    return ok;
}

int main(){
    const char* gguf = std::getenv("DA_TEST_GGUF");          // base f32 (DualDPT)
    const char* png  = std::getenv("DA_TEST_NATIVE_PNG");
    if (!gguf || !png) return 77;                            // skip if fixtures absent
    bool ok = test_dualdpt(gguf, png);

    const char* nanyview = std::getenv("DA_TEST_GGUF_NESTED_ANYVIEW");
    const char* nmetric  = std::getenv("DA_TEST_GGUF_NESTED_METRIC");
    if (nanyview && nmetric){
        ok = test_nested(nanyview, nmetric, png) && ok;
    } else {
        std::fprintf(stderr, "nested env not set, skipping nested checks\n");
    }

    const char* mono = std::getenv("DA_TEST_GGUF_MONO");
    const char* mpng = std::getenv("DA_TEST_MONO_PNG");
    if (mono && mpng){
        FILE* f = std::fopen(mono, "rb");
        if (f){ std::fclose(f); ok = test_mono(mono, mpng) && ok; }
        else std::fprintf(stderr, "mono gguf absent (%s), skipping mono checks\n", mono);
    } else {
        std::fprintf(stderr, "mono env not set, skipping mono checks\n");
    }
    return ok ? 0 : 1;
}

// models.go — the curated DA3 model catalog and a lazy-loading registry.
// Big checkpoints (giant/nested are ~5 GB each) are loaded on first use and
// evicted LRU so we never hold more than -max-live at once.
package main

import (
	"fmt"
	"log"
	"os"
	"path/filepath"
	"sync"
)

// ModelInfo describes one selectable model and its capabilities.
type ModelInfo struct {
	Name      string   `json:"name"`
	Label     string   `json:"label"`
	Backbone  string   `json:"backbone"`
	File      string   `json:"-"`           // primary gguf
	File2     string   `json:"-"`           // metric branch (nested only)
	Pose      bool     `json:"pose"`        // has camera pose -> multi-view fusion
	Gaussians bool     `json:"gaussians"`   // has GS head (gaussian output)
	Metric    bool     `json:"metric"`      // absolute metre scale
	Modes     []string `json:"modes"`       // subset of {"points","gaussians"}
	Default   bool     `json:"default"`     // pre-selected in the UI
}

// catalog is the curated set fetched by scripts/fetch_models.sh.
var catalog = []ModelInfo{
	{Name: "da3-small", Label: "DA3 Small — fast", Backbone: "ViT-S",
		File: "depth-anything-small-f32.gguf", Pose: true, Modes: []string{"points"}},
	{Name: "da3-base", Label: "DA3 Base — default", Backbone: "ViT-B",
		File: "depth-anything-base-q4_k.gguf", Pose: true, Modes: []string{"points"}, Default: true},
	{Name: "da3-large", Label: "DA3 Large — quality", Backbone: "ViT-L",
		File: "depth-anything-large-f32.gguf", Pose: true, Modes: []string{"points"}},
	{Name: "da3-giant", Label: "DA3 Giant — points + gaussians", Backbone: "ViT-g",
		File: "depth-anything-giant-f32.gguf", Pose: true, Gaussians: true, Modes: []string{"points", "gaussians"}},
	{Name: "da3-nested-metric", Label: "DA3 Nested — metric scale", Backbone: "ViT-g + ViT-L",
		File: "depth-anything-nested-anyview.gguf", File2: "depth-anything-nested-metric.gguf",
		Pose: true, Metric: true, Modes: []string{"points"}},
}

func findModel(name string) *ModelInfo {
	for i := range catalog {
		if catalog[i].Name == name {
			return &catalog[i]
		}
	}
	return nil
}

// loaded is one resident model context plus a serialization lock.
type loaded struct {
	ctx   uintptr
	runMu sync.Mutex
}

// Registry lazily loads/evicts model contexts. All inference goes through
// WithModel, which holds the registry lock across load+run so eviction can never
// free a context that is in use (max-live defaults to 1 for the big checkpoints).
type Registry struct {
	api       *capi
	dir       string
	threads   int32
	maxLive   int
	mu        sync.Mutex
	live      map[string]*loaded
	order     []string // LRU, oldest first
}

func NewRegistry(api *capi, dir string, threads, maxLive int) *Registry {
	if maxLive < 1 {
		maxLive = 1
	}
	return &Registry{api: api, dir: dir, threads: int32(threads), maxLive: maxLive,
		live: map[string]*loaded{}}
}

// available returns the catalog entries whose files are present on disk.
func (r *Registry) available() []ModelInfo {
	var out []ModelInfo
	for _, m := range catalog {
		if r.present(&m) {
			out = append(out, m)
		}
	}
	return out
}

func (r *Registry) present(m *ModelInfo) bool {
	if _, err := os.Stat(filepath.Join(r.dir, m.File)); err != nil {
		return false
	}
	if m.File2 != "" {
		if _, err := os.Stat(filepath.Join(r.dir, m.File2)); err != nil {
			return false
		}
	}
	return true
}

// WithModel loads (or reuses) the named model and runs fn with its context held
// under both the registry lock and the model's run lock.
func (r *Registry) WithModel(name string, fn func(ctx uintptr, mi *ModelInfo) error) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	mi := findModel(name)
	if mi == nil {
		return fmt.Errorf("unknown model %q", name)
	}
	if !r.present(mi) {
		return fmt.Errorf("model %q not downloaded (run scripts/fetch_models.sh)", name)
	}
	l, ok := r.live[name]
	if !ok {
		for len(r.order) >= r.maxLive && len(r.order) > 0 {
			ev := r.order[0]
			r.order = r.order[1:]
			r.api.freeCtx(r.live[ev].ctx)
			delete(r.live, ev)
			log.Printf("model: evicted %s", ev)
		}
		var ctx uintptr
		if mi.File2 != "" {
			ctx = r.api.loadNested(filepath.Join(r.dir, mi.File), filepath.Join(r.dir, mi.File2), r.threads)
		} else {
			ctx = r.api.load(filepath.Join(r.dir, mi.File), r.threads)
		}
		if ctx == 0 {
			return fmt.Errorf("failed to load model %q", name)
		}
		l = &loaded{ctx: ctx}
		r.live[name] = l
		r.order = append(r.order, name)
		log.Printf("model: loaded %s", name)
	} else {
		// move to MRU
		for i, n := range r.order {
			if n == name {
				r.order = append(r.order[:i], r.order[i+1:]...)
				break
			}
		}
		r.order = append(r.order, name)
	}
	return fn(l.ctx, mi)
}

package main

import "testing"

// Build a 2-view cloud: view 0 all NEAR (radius 1), view 1 all FAR (radius 8).
func mkCloud(nNear, nFar int) *Cloud {
	c := &Cloud{Counts: []int32{int32(nNear), int32(nFar)}}
	for i := 0; i < nNear+nFar; i++ {
		r := float32(1)
		if i >= nNear {
			r = 8
		}
		c.XYZ = append(c.XYZ, float32(i), 0, 0)
		c.RGB = append(c.RGB, 10, 20, 30)
		c.Rad = append(c.Rad, r)
	}
	c.N = nNear + nFar
	return c
}

func TestThinByDepthNoop(t *testing.T) {
	c := mkCloud(100, 100)
	if got := thinByDepth(c, 0); got != c {
		t.Fatalf("alpha=0 must return the same cloud unchanged")
	}
}

func TestThinByDepthNearHeavier(t *testing.T) {
	c := mkCloud(1000, 1000)
	out := thinByDepth(c, 1.0)
	if out == c {
		t.Fatalf("alpha>0 must return a new (thinned) cloud")
	}
	// invariants: N matches slices and rebuilt Counts sum to N
	if out.N != len(out.Rad) || 3*out.N != len(out.XYZ) || 3*out.N != len(out.RGB) {
		t.Fatalf("slice lengths inconsistent: N=%d rad=%d xyz=%d rgb=%d", out.N, len(out.Rad), len(out.XYZ), len(out.RGB))
	}
	var sum int32
	for _, k := range out.Counts {
		sum += k
	}
	if int(sum) != out.N {
		t.Fatalf("Counts sum %d != N %d", sum, out.N)
	}
	near, far := int(out.Counts[0]), int(out.Counts[1])
	// rRef = p10 radius = 1 (near), so near points keep at p=1, far at (1/8)^1 = 0.125.
	if near <= far {
		t.Fatalf("expected more near kept than far: near=%d far=%d", near, far)
	}
	if near < 950 { // near should be kept almost entirely
		t.Fatalf("near kept too few: %d/1000", near)
	}
	// far keep ratio ~0.125 -> ~125; allow generous band around error-diffusion result
	if far < 90 || far > 170 {
		t.Fatalf("far keep ratio off: far=%d (want ~125)", far)
	}
	t.Logf("alpha=1.0: near %d/1000  far %d/1000  total %d", near, far, out.N)
}

func TestThinByDepthStronger(t *testing.T) {
	c := mkCloud(1000, 1000)
	a1 := thinByDepth(c, 0.5)
	a2 := thinByDepth(c, 1.5)
	// Stronger bias must drop MORE far points (monotone in alpha) while near stays full.
	if int(a2.Counts[1]) >= int(a1.Counts[1]) {
		t.Fatalf("stronger alpha should keep fewer far: a1.far=%d a2.far=%d", a1.Counts[1], a2.Counts[1])
	}
	t.Logf("far kept: alpha0.5=%d  alpha1.5=%d", a1.Counts[1], a2.Counts[1])
}

package main

import (
	"encoding/binary"
	"math"
	"testing"
)

// A flat grid of points on the z=0 plane must yield normals along ±z, and the
// quaternion built from that normal must rotate local +z back onto the plane normal.
func TestEstimateNormalsPlane(t *testing.T) {
	c := &Cloud{}
	const G = 20
	step := float32(0.05)
	for i := 0; i < G; i++ {
		for j := 0; j < G; j++ {
			c.XYZ = append(c.XYZ, float32(i)*step, float32(j)*step, 0)
			c.RGB = append(c.RGB, 200, 200, 200)
			c.Rad = append(c.Rad, step) // spacing == radius
		}
	}
	c.N = G * G
	c.Counts = []int32{int32(c.N)}
	estimateNormals(c)
	if len(c.Normals) != 3*c.N {
		t.Fatalf("normals not filled: %d", len(c.Normals))
	}
	// interior point (well away from the border) should have a clean ±z normal
	mid := (G/2)*G + G/2
	nz := math.Abs(float64(c.Normals[3*mid+2]))
	nxy := math.Hypot(float64(c.Normals[3*mid]), float64(c.Normals[3*mid+1]))
	if nz < 0.98 || nxy > 0.1 {
		t.Fatalf("interior normal not along z: n=(%.3f,%.3f,%.3f)", c.Normals[3*mid], c.Normals[3*mid+1], c.Normals[3*mid+2])
	}
	// quaternion's 3rd basis axis (local z) must equal the normal (up to sign)
	q := quatFromNormal(0, 0, 1)
	w, x, y, z := q[0], q[1], q[2], q[3]
	// 3rd column of R(q)
	cz := [3]float32{2 * (x*z + w*y), 2 * (y*z - w*x), 1 - 2*(x*x+y*y)}
	if math.Abs(float64(cz[2])-1) > 1e-5 || math.Hypot(float64(cz[0]), float64(cz[1])) > 1e-5 {
		t.Fatalf("quatFromNormal(z) local-z axis wrong: (%.4f,%.4f,%.4f)", cz[0], cz[1], cz[2])
	}
}

// quatFromNormal must return a unit quaternion whose local-z axis matches an arbitrary
// input normal (up to sign is not needed here — it should match exactly in direction).
func TestQuatFromNormalArbitrary(t *testing.T) {
	n := [3]float64{0.3, -0.6, 0.74}
	l := math.Sqrt(n[0]*n[0] + n[1]*n[1] + n[2]*n[2])
	nx, ny, nz := float32(n[0]/l), float32(n[1]/l), float32(n[2]/l)
	q := quatFromNormal(nx, ny, nz)
	qn := math.Sqrt(float64(q[0]*q[0] + q[1]*q[1] + q[2]*q[2] + q[3]*q[3]))
	if math.Abs(qn-1) > 1e-4 {
		t.Fatalf("quat not unit: |q|=%.5f", qn)
	}
	w, x, y, z := q[0], q[1], q[2], q[3]
	cz := [3]float32{2 * (x*z + w*y), 2 * (y*z - w*x), 1 - 2*(x*x+y*y)}
	d := float64(cz[0]*nx + cz[1]*ny + cz[2]*nz)
	if d < 0.999 {
		t.Fatalf("local-z axis misaligned with normal: dot=%.5f", d)
	}
}

// orderWithinFramesByRadius must sort each frame block ascending by radius while
// preserving frame boundaries (Counts) and keeping XYZ/Rad in lockstep.
func TestOrderWithinFrames(t *testing.T) {
	c := &Cloud{Counts: []int32{3, 2}}
	// frame 0: radii 3,1,2 ; frame 1: radii 5,4  (deliberately unsorted)
	rads := []float32{3, 1, 2, 5, 4}
	for i, r := range rads {
		c.XYZ = append(c.XYZ, float32(i), 0, 0) // tag x = original index
		c.RGB = append(c.RGB, byte(i), 0, 0)
		c.Rad = append(c.Rad, r)
	}
	c.N = len(rads)
	orderWithinFramesByRadius(c)
	// frame 0 block [0,3) ascending: 1,2,3 ; frame 1 block [3,5): 4,5
	want := []float32{1, 2, 3, 4, 5}
	for i := range want {
		if c.Rad[i] != want[i] {
			t.Fatalf("radii not per-frame sorted: got %v want %v", c.Rad, want)
		}
	}
	// XYZ.x (original index tag) must have moved with the radius
	if c.XYZ[0] != 1 || c.XYZ[3] != 2 || c.XYZ[6] != 0 { // idx of r=1 is 1, r=2 is 2, r=3 is 0
		t.Fatalf("XYZ not permuted with radius: %v", c.XYZ)
	}
	// frame boundary intact: block 1 stays {4,5}, not mixed with frame 0
	if c.Rad[3] < c.Rad[2] {
		t.Fatalf("frame boundary violated: %v", c.Rad)
	}
}

// dedupFirstFrame must keep a cell for the FIRST frame that fills it and drop later
// frames' coincident re-observations, while keeping genuinely new cells and rebuilding
// Counts. This is what makes the reveal purely additive.
func TestDedupFirstFrame(t *testing.T) {
	c := &Cloud{Counts: []int32{2, 3}}
	// frame 0: two points in distinct cells (0,*,*) and (5,*,*)
	// frame 1: one coincident with frame0's first cell (should drop), two genuinely new
	pts := [][3]float32{
		{0.1, 0, 0}, {5.1, 0, 0}, // frame 0 -> cells x=0, x=5
		{0.2, 0, 0},               // frame 1 -> cell x=0 (dup of frame0) -> DROP
		{9.1, 0, 0}, {12.1, 0, 0}, // frame 1 -> new cells x=9, x=12 -> KEEP
	}
	for _, p := range pts {
		c.XYZ = append(c.XYZ, p[0], p[1], p[2])
		c.RGB = append(c.RGB, 1, 2, 3)
		c.Rad = append(c.Rad, 0.1)
	}
	c.N = len(pts)
	dropped := dedupFirstFrame(c, 1.0)
	if dropped != 1 {
		t.Fatalf("expected 1 coincident point dropped, got %d", dropped)
	}
	if c.N != 4 {
		t.Fatalf("expected 4 points kept, got %d", c.N)
	}
	// Counts rebuilt: frame0 keeps both, frame1 keeps 2 of its 3 (the dup dropped)
	if c.Counts[0] != 2 || c.Counts[1] != 2 {
		t.Fatalf("Counts not rebuilt correctly: %v (want [2 2])", c.Counts)
	}
	// kept points remain a frame-major subsequence (frame0's cells come before frame1's new ones)
	if c.XYZ[0] != 0.1 || c.XYZ[3] != 5.1 || c.XYZ[6] != 9.1 || c.XYZ[9] != 12.1 {
		t.Fatalf("frame order not preserved: %v", c.XYZ)
	}
}

// countLess is the reveal-boundary lookup: how many cubes have first-frame < k.
func TestCountLess(t *testing.T) {
	s := []int{0, 0, 1, 1, 1, 3, 4}
	for _, tc := range []struct{ k, want int }{{0, 0}, {1, 2}, {2, 5}, {3, 5}, {4, 6}, {99, 7}} {
		if g := countLess(s, tc.k); g != tc.want {
			t.Fatalf("countLess(%d)=%d want %d", tc.k, g, tc.want)
		}
	}
}

// Voxelising a cloud that fills a known box must produce one cube per occupied cell,
// each a 32-byte record with the expected half-extent in its scale fields.
func TestCloudToCubes(t *testing.T) {
	c := &Cloud{}
	// 8 points, 2 per cell across 4 distinct unit cells at cell=1.0
	pts := [][3]float32{
		{0.1, 0.1, 0.1}, {0.9, 0.9, 0.9}, // cell (0,0,0)
		{1.2, 0.1, 0.1}, {1.8, 0.5, 0.5}, // cell (1,0,0)
		{0.1, 1.3, 0.1}, // cell (0,1,0)
		{0.1, 0.1, 2.4}, // cell (0,0,2)
	}
	for _, p := range pts {
		c.XYZ = append(c.XYZ, p[0], p[1], p[2])
		c.RGB = append(c.RGB, 100, 150, 200)
		c.Rad = append(c.Rad, 0.1)
	}
	c.N = len(pts)
	blob := cloudToCubes(c, c.N, 1.0)
	nCubes := len(blob) / splatRow
	if nCubes != 4 {
		t.Fatalf("expected 4 occupied cells, got %d", nCubes)
	}
	// each record's scale fields = half-extent = 0.5*cell*voxelFill
	wantHalf := float32(0.5 * 1.0 * voxelFill)
	sx := math.Float32frombits(binary.LittleEndian.Uint32(blob[12:]))
	if math.Abs(float64(sx-wantHalf)) > 1e-6 {
		t.Fatalf("cube half-extent = %.4f, want %.4f", sx, wantHalf)
	}
	// empty cell size guard
	if cloudToCubes(c, c.N, 0) != nil {
		t.Fatalf("cell<=0 must yield nil")
	}
}

func TestParseTemporalMeshManifest(t *testing.T) {
	b := make([]byte, 32+2*24)
	copy(b, "DTVM")
	binary.LittleEndian.PutUint16(b[4:], 1)
	binary.LittleEndian.PutUint16(b[6:], 32)
	binary.LittleEndian.PutUint32(b[12:], 9)
	binary.LittleEndian.PutUint32(b[16:], 2)
	binary.LittleEndian.PutUint32(b[20:], 1)
	binary.LittleEndian.PutUint32(b[24:], math.Float32bits(0.125))
	binary.LittleEndian.PutUint32(b[28:], 24)
	m, ok := parseTemporalMeshManifest("surface.dtvm", b)
	if !ok {
		t.Fatal("valid DTVM header rejected")
	}
	if m.File != "surface.dtvm" || m.Format != "dtvm-1" || m.Frames != 9 ||
		m.Faces != 2 || m.FinalFaces != 1 || m.VoxelSize != 0.125 || m.Bytes != len(b) {
		t.Fatalf("unexpected manifest: %+v", m)
	}
	if _, ok := parseTemporalMeshManifest("bad.dtvm", b[:len(b)-1]); ok {
		t.Fatal("truncated DTVM accepted")
	}
}

